const REQUIRED_SHAPE = Object.freeze({
  schemaVersion: "storycore-harbour.project.v1",
  project: [
    "id",
    "title",
    "language",
    "format",
    "durationMinutes",
    "audience",
    "tone",
    "sourceIdea",
    "createdAt",
    "updatedAt",
  ],
  productionBible: [
    "logline",
    "synopsis",
    "themes[]",
    "visualDirection.style",
    "visualDirection.palette[]",
    "visualDirection.lighting",
    "visualDirection.cameraLanguage",
    "continuityRules[]",
  ],
  character: [
    "id",
    "name",
    "role",
    "goal",
    "conflict",
    "visualIdentity",
    "continuityRules[]",
  ],
  location: [
    "id",
    "name",
    "purpose",
    "visualIdentity",
    "continuityRules[]",
  ],
  scene: [
    "id",
    "order",
    "title",
    "purpose",
    "locationId",
    "characterIds[]",
    "durationSeconds",
    "shots[]",
  ],
  shot: [
    "id",
    "order",
    "framing",
    "camera",
    "action",
    "dialogue",
    "sound",
    "characterIds[]",
    "generationPrompt",
  ],
  continuityReport: ["score", "warnings[]", "checkedAt"],
  warning: ["severity", "message", "sceneId"],
});

export function createRepairPrompt(input, errors) {
  return JSON.stringify({
    task: "Rebuild the complete StoryCore Harbour project from the source input. The previous answer failed validation, so return a fresh self-contained project rather than a patch.",
    input,
    validationErrors: errors,
    requiredShape: REQUIRED_SHAPE,
    hardRules: [
      "Return exactly one JSON object and nothing else.",
      "Include every required field listed in requiredShape, even when a string is intentionally empty.",
      "Create exactly 3 scenes and exactly 1 shot inside each scene.",
      "Create 1-3 characters and 1-3 locations; every scene locationId must reference a declared location.",
      "Every scene characterIds entry must reference a declared character.",
      "Every shot characterIds entry must reference a declared character also listed in its parent scene.",
      "Use unique ids, scene orders 1,2,3, and shot order 1 in every scene.",
      "dialogue and sound are always strings; use an empty string when there is intentionally none.",
      "themes, palette, continuityRules, characterIds, shots, and warnings are always arrays.",
      "warning severity is only info, warning, or error; sceneId is a declared scene id or null.",
      "continuityReport.score is a number from 0 through 100.",
      "Preserve input.title exactly when it is non-empty, and preserve input language, format, duration, audience, tone, and source idea.",
      "Keep the entire JSON below 12000 characters; do not omit required structure to save space.",
      "Before returning, silently verify the project contains project, productionBible, characters, locations, scenes, and continuityReport.",
    ],
    sizeBudget: {
      maxCharacters: 12_000,
      scenes: 3,
      shotsPerScene: 1,
      characters: "1-3",
      locations: "1-3",
      synopsisMaxWords: 80,
      descriptionMaxWords: 40,
      generationPromptMaxWords: 60,
      maxThemes: 3,
      maxProductionContinuityRules: 3,
      maxEntityContinuityRules: 2,
    },
    discardPreviousResponse: true,
  });
}
